/** CADX brand — raster assets generated by scripts/make_brand_assets.py
 *  from the source PNGs. `wordmark` renders the full CAD+X lockup
 *  (transparent background), otherwise the rounded app-icon tile. */
export default function Logo({
  size = 20,
  wordmark = false,
  className = "",
}: {
  size?: number;
  wordmark?: boolean;
  className?: string;
}) {
  if (wordmark) {
    // width-driven: the wordmark (aspect ~1.5:1) should fill the sidebar —
    // inline style because Tailwind preflight's img{height:auto} overrides
    // attributes
    return (
      <img
        src="/brand/wordmark.png"
        alt="CADX"
        style={{ width: Math.round(size * 3), height: "auto" }}
        className={className}
      />
    );
  }
  return (
    <img
      src="/brand/icon.png"
      alt="CADX"
      style={{ width: size, height: size }}
      className={`rounded-md ${className}`}
    />
  );
}
